const KEY = "proto_bookmarks_v1";
const SEED_FLAG = "proto_bookmarks_seeded_v1";
let items = [];
try { items = JSON.parse(localStorage.getItem(KEY) || "[]"); } catch (e) { items = []; }

// Pre-load a small, varied set of example links once, so searching has
// something to work with. Anything the client saved is kept alongside these.
const SEED = [
  { url: "https://www.nytimes.com/article", host: "nytimes.com", title: "The Science of a Good Night's Sleep", site: "The New York Times", desc: "What researchers now understand about sleep cycles, and small habits that improve rest.", ago: 1000 * 60 * 60 * 2 },
  { url: "https://arstechnica.com/the-history-of-the-web-bookmark", host: "arstechnica.com", title: "The long, strange history of the web bookmark", site: "Ars Technica", desc: "How saving links evolved from a browser afterthought into its own category of tools.", ago: 1000 * 60 * 60 * 26 },
  { url: "https://medium.com/organising-my-reading-list", host: "medium.com", title: "How I Finally Organised My Reading List", site: "Medium", desc: "A personal system for saving articles you actually come back to.", ago: 1000 * 60 * 60 * 50 },
  { url: "https://github.com", host: "github.com", title: "GitHub — Where the world builds software", site: "GitHub", desc: "GitHub is where over 100 million developers shape the future of software, together.", ago: 1000 * 60 * 60 * 90 },
  { url: "https://en.wikipedia.org/wiki/Bookmark_(World_Wide_Web)", host: "wikipedia.org", title: "Bookmark (World Wide Web) — Wikipedia", site: "Wikipedia", desc: "A bookmark is a URI that is stored for later retrieval in any of various storage formats.", ago: 1000 * 60 * 60 * 120 }
];
if (!localStorage.getItem(SEED_FLAG)) {
  const now = Date.now();
  const seeded = SEED.map((s, i) => ({
    id: now - 1000 - i, url: s.url, host: s.host, title: s.title,
    site: s.site, desc: s.desc, savedAt: now - s.ago
  }));
  items = items.concat(seeded);
  items.sort((a, b) => b.savedAt - a.savedAt);
  localStorage.setItem(SEED_FLAG, "1");
  localStorage.setItem(KEY, JSON.stringify(items));
}

let query = "";

function persist() { localStorage.setItem(KEY, JSON.stringify(items)); }

