const listEl = document.getElementById("list");
const emptyEl = document.getElementById("empty");
const listLabel = document.getElementById("listLabel");
const searchBox = document.getElementById("searchBox");
const noResults = document.getElementById("noResults");
const noResultsMsg = document.getElementById("noResultsMsg");
const clearSearchBtn = document.getElementById("clearSearch");

function matches(it, q) {
  const hay = [it.title, it.site, it.host, it.url, it.desc].join(" ").toLowerCase();
  return q.split(/\s+/).filter(Boolean).every(term => hay.includes(term));
}

function highlight(text, q) {
  let out = escapeHtml(text);
  const terms = q.split(/\s+/).filter(Boolean).map(t => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  if (terms.length === 0) return out;
  const re = new RegExp("(" + terms.join("|") + ")", "gi");
  return out.replace(re, "<mark>$1</mark>");
}

function render() {
  listEl.innerHTML = "";
  const q = query.trim().toLowerCase();

  // No links at all -> initial empty state, hide search.
  if (items.length === 0) {
    emptyEl.style.display = "block";
    noResults.style.display = "none";
    searchBox.style.display = "none";
    listLabel.style.display = "none";
    return;
  }

  emptyEl.style.display = "none";
  searchBox.style.display = "flex";
  clearSearchBtn.style.display = q ? "block" : "none";

  const visible = q ? items.filter(it => matches(it, q)) : items;

  if (visible.length === 0) {
    listLabel.style.display = "none";
    noResults.style.display = "block";
    noResultsMsg.textContent = `Nothing matched “${query.trim()}”. Try a different word.`;
    return;
  }

  noResults.style.display = "none";
  listLabel.style.display = "block";
  listLabel.textContent = q ? `${visible.length} matching link${visible.length > 1 ? "s" : ""}` : "Saved links";

  visible.forEach(it => {
    const li = document.createElement("li");
    li.className = "item";
    const initial = (it.site || it.host || "?").charAt(0).toUpperCase();
    li.innerHTML = `
      <p class="title"><a href="${it.url}" target="_blank" rel="noopener">${highlight(it.title, q)}</a></p>
      <div class="meta">
        <span class="favicon">${escapeHtml(initial)}</span>
        <span>${highlight(it.site || it.host, q)}</span>
        <span>·</span>
        <span>${highlight(it.host, q)}</span>
        <span>·</span>
        <span>saved ${timeAgo(it.savedAt)}</span>
      </div>
      ${it.desc ? `<p class="desc">${highlight(it.desc, q)}</p>` : ""}
    `;
    listEl.appendChild(li);
  });
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;" }[c]));
}

