137	<body>
138	<header>
139	  <h1>My Bookmarks</h1>
140	  <p>Save a link and I'll fill in its details automatically.</p>
141	</header>
142	<main>
143	  <div class="save-box">
144	    <div class="save-row">
145	      <input id="url" type="text" placeholder="Paste a link here, e.g. https://…" autocomplete="off">
146	      <button id="saveBtn">Save</button>
147	    </div>
148	    <div class="hint">Tip: paste any web address and press Save.</div>
149	    <div class="status" id="status"></div>
150	  </div>
151	
152	  <div class="search-box" id="searchBox" style="display:none;">
153	    <span class="search-icon">⌕</span>
154	    <input id="search" type="text" placeholder="Search your links by word, site, or address…" autocomplete="off">
155	    <button id="clearSearch" class="clear-search" style="display:none;" title="Clear search">✕</button>
156	  </div>
157	
158	  <p class="section-label" id="listLabel" style="display:none;">Saved links</p>
159	  <ul class="list" id="list"></ul>
160	
161	  <div class="empty" id="noResults" style="display:none;">
162	    <div class="big">No matching links</div>
163	    <div id="noResultsMsg">Nothing matched your search. Try a different word.</div>
164	  </div>
165	
166	  <div class="empty" id="empty">
167	    <div class="big">No links saved yet</div>
168	    <div>Paste a link above and press Save to add your first bookmark.</div>
169	  </div>
170	</main>
171	
172	<script>
173	  // --- Simulated metadata lookup -------------------------------------------
174	  // In the real app, details (title, site, summary) would be fetched from the
175	  // page automatically. In this prototype that lookup is SIMULATED so we can
176	  // explore the behaviour without a live connection.
177	  const KNOWN = {
178	    "nytimes.com": { title: "The Science of a Good Night's Sleep", site: "The New York Times", desc: "What researchers now understand about sleep cycles, and small habits that improve rest." },
179	    "wikipedia.org": { title: "Bookmark (World Wide Web) — Wikipedia", site: "Wikipedia", desc: "A bookmark is a URI that is stored for later retrieval in any of various storage formats." },
180	    "github.com": { title: "GitHub — Where the world builds software", site: "GitHub", desc: "GitHub is where over 100 million developers shape the future of software, together." },
181	    "medium.com": { title: "How I Finally Organised My Reading List", site: "Medium", desc: "A personal system for saving articles you actually come back to." },
182	    "youtube.com": { title: "Deep Focus — Ambient Study Music", site: "YouTube", desc: "Three hours of calm background music for concentration and reading." },
183	    "arstechnica.com": { title: "The long, strange history of the web bookmark", site: "Ars Technica", desc: "How saving links evolved from a browser afterthought into its own category of tools." }
184	  };
185	
186	  function domainOf(url) {
187	    try {
188	      let u = url.trim();
189	      if (!/^https?:\/\//i.test(u)) u = "https://" + u;
190	      const host = new URL(u).hostname.replace(/^www\./, "");
191	      return host;
192	    } catch (e) { return null; }
193	  }
194	
195	  function titleCase(s) {
196	    return s.replace(/[-_]/g, " ").replace(/\b\w/g, c => c.toUpperCase());
197	  }
198	
199	  function lookup(url) {
200	    const host = domainOf(url);
201	    if (!host) return null;
202	    // known site match (by root domain)
203	    for (const key in KNOWN) {
204	      if (host === key || host.endsWith("." + key)) {
205	        return Object.assign({ host }, KNOWN[key]);
206	      }
207	    }
208	    // fallback: derive a plausible title from the path/domain
209	    let path = "";
210	    try {
211	      let u = url.trim();
212	      if (!/^https?:\/\//i.test(u)) u = "https://" + u;
213	      path = new URL(u).pathname.split("/").filter(Boolean).pop() || "";
214	    } catch (e) {}
215	    const root = host.split(".")[0];
216	    const guessed = path ? titleCase(path.replace(/\.\w+$/, "")) : titleCase(root);
217	    return { host, title: guessed || host, site: titleCase(root), desc: "" };
218	  }
219	
220	  // --- State ----------------------------------------------------------------
221	  const KEY = "proto_bookmarks_v1";
222	  const SEED_FLAG = "proto_bookmarks_seeded_v1";
223	  let items = [];
224	  try { items = JSON.parse(localStorage.getItem(KEY) || "[]"); } catch (e) { items = []; }
225	
226	  // Pre-load a small, varied set of example links once, so searching has
227	  // something to work with. Anything the client saved is kept alongside these.
228	  const SEED = [
229	    { url: "https://www.nytimes.com/article", host: "nytimes.com", title: "The Science of a Good Night's Sleep", site: "The New York Times", desc: "What researchers now understand about sleep cycles, and small habits that improve rest.", ago: 1000 * 60 * 60 * 2 },
230	    { url: "https://arstechnica.com/the-history-of-the-web-bookmark", host: "arstechnica.com", title: "The long, strange history of the web bookmark", site: "Ars Technica", desc: "How saving links evolved from a browser afterthought into its own category of tools.", ago: 1000 * 60 * 60 * 26 },
231	    { url: "https://medium.com/organising-my-reading-list", host: "medium.com", title: "How I Finally Organised My Reading List", site: "Medium", desc: "A personal system for saving articles you actually come back to.", ago: 1000 * 60 * 60 * 50 },
232	    { url: "https://github.com", host: "github.com", title: "GitHub — Where the world builds software", site: "GitHub", desc: "GitHub is where over 100 million developers shape the future of software, together.", ago: 1000 * 60 * 60 * 90 },
233	    { url: "https://en.wikipedia.org/wiki/Bookmark_(World_Wide_Web)", host: "wikipedia.org", title: "Bookmark (World Wide Web) — Wikipedia", site: "Wikipedia", desc: "A bookmark is a URI that is stored for later retrieval in any of various storage formats.", ago: 1000 * 60 * 60 * 120 }
234	  ];
235	  if (!localStorage.getItem(SEED_FLAG)) {
236	    const now = Date.now();
237	    const seeded = SEED.map((s, i) => ({
238	      id: now - 1000 - i, url: s.url, host: s.host, title: s.title,
239	      site: s.site, desc: s.desc, savedAt: now - s.ago
240	    }));
241	    items = items.concat(seeded);
242	    items.sort((a, b) => b.savedAt - a.savedAt);
243	    localStorage.setItem(SEED_FLAG, "1");
244	    localStorage.setItem(KEY, JSON.stringify(items));
245	  }
246	
247	  let query = "";
248	
249	  function persist() { localStorage.setItem(KEY, JSON.stringify(items)); }
250	
251	  function timeAgo(ts) {
252	    const s = Math.floor((Date.now() - ts) / 1000);
253	    if (s < 60) return "just now";
254	    const m = Math.floor(s / 60); if (m < 60) return m + " min ago";
255	    const h = Math.floor(m / 60); if (h < 24) return h + " h ago";
256	    const d = Math.floor(h / 24); return d + " d ago";
257	  }
258	
259	  const listEl = document.getElementById("list");
260	  const emptyEl = document.getElementById("empty");
261	  const listLabel = document.getElementById("listLabel");
262	  const searchBox = document.getElementById("searchBox");
263	  const noResults = document.getElementById("noResults");
264	  const noResultsMsg = document.getElementById("noResultsMsg");
265	  const clearSearchBtn = document.getElementById("clearSearch");
266	
267	  function matches(it, q) {
268	    const hay = [it.title, it.site, it.host, it.url, it.desc].join(" ").toLowerCase();
269	    return q.split(/\s+/).filter(Boolean).every(term => hay.includes(term));
270	  }
271	
272	  function highlight(text, q) {
273	    let out = escapeHtml(text);
274	    const terms = q.split(/\s+/).filter(Boolean).map(t => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
275	    if (terms.length === 0) return out;
276	    const re = new RegExp("(" + terms.join("|") + ")", "gi");
277	    return out.replace(re, "<mark>$1</mark>");
278	  }
279	
280	  function render() {
281	    listEl.innerHTML = "";
282	    const q = query.trim().toLowerCase();
283	
284	    // No links at all -> initial empty state, hide search.
285	    if (items.length === 0) {
286	      emptyEl.style.display = "block";
287	      noResults.style.display = "none";
288	      searchBox.style.display = "none";
289	      listLabel.style.display = "none";
290	      return;
291	    }
292	
293	    emptyEl.style.display = "none";
294	    searchBox.style.display = "flex";
295	    clearSearchBtn.style.display = q ? "block" : "none";
296	
297	    const visible = q ? items.filter(it => matches(it, q)) : items;
298	
299	    if (visible.length === 0) {
300	      listLabel.style.display = "none";
301	      noResults.style.display = "block";
302	      noResultsMsg.textContent = `Nothing matched “${query.trim()}”. Try a different word.`;
303	      return;
304	    }
305	
306	    noResults.style.display = "none";
307	    listLabel.style.display = "block";
308	    listLabel.textContent = q ? `${visible.length} matching link${visible.length > 1 ? "s" : ""}` : "Saved links";
309	
310	    visible.forEach(it => {
311	      const li = document.createElement("li");
312	      li.className = "item";
313	      const initial = (it.site || it.host || "?").charAt(0).toUpperCase();
314	      li.innerHTML = `
315	        <p class="title"><a href="${it.url}" target="_blank" rel="noopener">${highlight(it.title, q)}</a></p>
316	        <div class="meta">
317	          <span class="favicon">${escapeHtml(initial)}</span>
318	          <span>${highlight(it.site || it.host, q)}</span>
319	          <span>·</span>
320	          <span>${highlight(it.host, q)}</span>
321	          <span>·</span>
322	          <span>saved ${timeAgo(it.savedAt)}</span>
323	        </div>
324	        ${it.desc ? `<p class="desc">${highlight(it.desc, q)}</p>` : ""}
325	      `;
326	      listEl.appendChild(li);
327	    });
328	  }
329	
330	  function escapeHtml(s) {
331	    return String(s).replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;" }[c]));
332	  }
333	
334	  const urlEl = document.getElementById("url");
335	  const btn = document.getElementById("saveBtn");
336	  const statusEl = document.getElementById("status");
337	
338	  function setStatus(msg, cls) {
339	    statusEl.textContent = msg;
340	    statusEl.className = "status " + (cls || "");
341	  }
342	
343	  function save() {
344	    const raw = urlEl.value.trim();
345	    if (!raw) { setStatus("Please paste a link first.", "error"); return; }
346	    const host = domainOf(raw);
347	    if (!host || !host.includes(".")) { setStatus("That doesn't look like a valid link.", "error"); return; }
348	
349	    btn.disabled = true;
350	    setStatus("Fetching details…", "saving");
351	
352	    // Simulate the automatic detail lookup with a short delay.
353	    setTimeout(() => {
354	      const meta = lookup(raw);
355	      let normalized = raw;
356	      if (!/^https?:\/\//i.test(normalized)) normalized = "https://" + normalized;
357	      items.unshift({
358	        id: Date.now(),
359	        url: normalized,
360	        host: meta.host,
361	        title: meta.title,
362	        site: meta.site,
363	        desc: meta.desc,
364	        savedAt: Date.now()
365	      });
366	      persist();
367	      render();
368	      urlEl.value = "";
369	      btn.disabled = false;
370	      setStatus("Saved — details filled in automatically.", "saved");
371	      setTimeout(() => setStatus("", ""), 2500);
372	      urlEl.focus();
373	    }, 650);
374	  }
375	
376	  btn.addEventListener("click", save);
377	  urlEl.addEventListener("keydown", e => { if (e.key === "Enter") save(); });
378	
379	  const searchEl = document.getElementById("search");
380	  searchEl.addEventListener("input", e => { query = e.target.value; render(); });
381	  clearSearchBtn.addEventListener("click", () => { query = ""; searchEl.value = ""; searchEl.focus(); render(); });
382	
383	  render();
384	  document.body.setAttribute("data-harness-ready", "true");
385	</script>
386	</body>
387	</html>
