function save(){ const raw=urlEl.value.trim(); if(!raw){ setStatus("Please paste a link first.","error"); return; } const host=domainOf(raw); if(!host||!host.includes(".")){ setStatus("That doesn't look like a valid link.","error"); return; }
  btn.disabled=true; setStatus("Fetching details…","saving");
  setTimeout(()=>{ const meta=lookup(raw); let n=raw; if(!/^https?:\/\//i.test(n)) n="https://"+n; items.unshift({id:Date.now(),url:n,host:meta.host,title:meta.title,site:meta.site,desc:meta.desc,savedAt:Date.now(),tags:[],note:""}); persist(); render(); urlEl.value=""; btn.disabled=false; setStatus("Saved — details filled in automatically.","saved"); setTimeout(()=>setStatus("",""),2500); urlEl.focus(); },650);
}

