:root {
  --bg: #f6f7f9;
  --card: #ffffff;
  --line: #e4e7ec;
  --text: #1a1d24;
  --muted: #6b7280;
  --accent: #2563eb;
  --accent-soft: #eaf1ff;
  --danger: #dc2626;
  --warn: #d97706;
  --ok: #059669;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}
header {
  background: var(--card);
  border-bottom: 1px solid var(--line);
  padding: 16px 20px;
  position: sticky;
  top: 0;
  z-index: 5;
}
.header-inner { max-width: 720px; margin: 0 auto; }
header h1 { margin: 0; font-size: 20px; }
header .tagline { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
main { max-width: 720px; margin: 0 auto; padding: 20px; }

.save-box {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 20px;
  box-shadow: 0 1px 2px rgba(16,24,40,0.04);
}
.save-row { display: flex; gap: 8px; }
.save-row input {
  flex: 1;
  padding: 12px 14px;
  font-size: 15px;
  border: 1px solid var(--line);
  border-radius: 8px;
  outline: none;
}
.save-row input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.save-row button {
  padding: 12px 18px;
  font-size: 15px;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  white-space: nowrap;
}
.save-row button:disabled { opacity: 0.5; cursor: default; }
.hint { color: var(--muted); font-size: 12px; margin: 8px 0 0; }
.status { font-size: 13px; margin: 10px 0 0; min-height: 18px; }
.status.saving { color: var(--accent); }
.status.saved { color: var(--ok); }
.status.error { color: var(--danger); }
.status-action { display: inline-block; margin-top: 4px; }

.search-box {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 4px 12px;
  margin-bottom: 16px;
}
.search-box:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.search-box .search-icon { color: var(--muted); font-size: 18px; }
.search-box input { flex: 1; border: none; outline: none; padding: 9px 0; font-size: 15px; background: transparent; }
.search-box .clear-search { border: none; background: transparent; color: var(--muted); cursor: pointer; font-size: 14px; padding: 4px; }

mark { background: #fef3c7; color: inherit; border-radius: 3px; padding: 0 1px; }

.tabs { display: flex; gap: 6px; margin-bottom: 16px; flex-wrap: wrap; }
.tabs button {
  border: 1px solid var(--line);
  background: var(--card);
  color: var(--text);
  border-radius: 999px;
  padding: 7px 14px;
  font-size: 13px;
  cursor: pointer;
  display: inline-flex;
  gap: 6px;
  align-items: center;
}
.tabs button .count { background: var(--bg); color: var(--muted); border-radius: 999px; padding: 0 7px; font-size: 12px; }
.tabs button.on { background: var(--accent); color: #fff; border-color: var(--accent); }
.tabs button.on .count { background: rgba(255,255,255,0.25); color: #fff; }

.section-label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); margin: 0 0 10px; }

.list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 12px; }
.item {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px 16px;
  box-shadow: 0 1px 2px rgba(16,24,40,0.04);
}
.item.is-toread { border-color: #fcd8a6; }
.item.is-archived { opacity: 0.72; }
.item.flash { animation: flash 1.6s ease; }
@keyframes flash {
  0%,100% { box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
  20% { box-shadow: 0 0 0 3px #fcd34d; }
}
.item .title { font-size: 16px; font-weight: 600; margin: 0 0 2px; }
.item .title a { color: var(--text); text-decoration: none; }
.item .title a:hover { text-decoration: underline; }
.item .meta { font-size: 12px; color: var(--muted); display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.item .favicon {
  width: 16px; height: 16px; border-radius: 4px; background: var(--accent-soft);
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 10px; color: var(--accent); font-weight: 700;
}
.item .desc { font-size: 14px; color: #384150; margin: 8px 0 0; }
.note { font-size: 14px; color: #374151; margin: 10px 0 0; padding: 10px 12px; background: #fafafa; border-left: 3px solid var(--line); border-radius: 4px; }
.note p { margin: 0 0 6px; } .note p:last-child { margin-bottom: 0; }
.note ul { margin: 4px 0; padding-left: 20px; } .note li { margin: 2px 0; }
.note a { color: var(--accent); }

.tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.tag { font-size: 12px; background: var(--accent-soft); color: #1e40af; border-radius: 999px; padding: 3px 10px; }

.item-actions { margin-top: 10px; display: flex; gap: 18px; align-items: center; flex-wrap: wrap; }
.link-btn { border: none; background: transparent; color: var(--accent); font-size: 13px; cursor: pointer; padding: 4px 0; font-weight: 600; }
.toread-btn { border: none; background: transparent; color: var(--muted); font-size: 13px; cursor: pointer; padding: 4px 0; font-weight: 600; }
.toread-btn.on { color: var(--warn); }
.toread-flag { font-size: 12px; color: var(--warn); font-weight: 600; margin-left: auto; }
.muted-btn { border: none; background: transparent; color: var(--muted); font-size: 13px; cursor: pointer; padding: 4px 0; font-weight: 600; }
.danger-btn { border: none; background: transparent; color: var(--danger); font-size: 13px; cursor: pointer; padding: 4px 0; font-weight: 600; }

.confirm {
  display: flex; gap: 12px; align-items: center; margin-top: 10px;
  padding: 8px 10px; background: #fef2f2; border: 1px solid #fecaca;
  border-radius: 8px; font-size: 13px; color: #991b1b; flex-wrap: wrap;
}

.editor { margin-top: 12px; border-top: 1px dashed var(--line); padding-top: 12px; }
.editor .field { margin-bottom: 14px; position: relative; }
.editor label { display: block; font-size: 12px; font-weight: 600; color: var(--muted); margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.03em; }
.editor .text-input, .editor textarea {
  width: 100%; border: 1px solid var(--line); border-radius: 8px;
  padding: 10px; font: inherit; font-size: 14px; outline: none;
}
.editor textarea { resize: vertical; }
.editor .text-input:focus, .editor textarea:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.chip-input { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; border: 1px solid var(--line); border-radius: 8px; padding: 6px 8px; }
.chip-input:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.chip-input input { flex: 1; min-width: 140px; border: none; outline: none; font: inherit; font-size: 14px; padding: 4px; }
.editable-tag { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; background: var(--accent-soft); color: #1e40af; border-radius: 999px; padding: 3px 8px 3px 10px; }
.editable-tag button { border: none; background: transparent; color: #1e40af; cursor: pointer; font-size: 12px; line-height: 1; padding: 0; }
.suggest {
  position: absolute; left: 0; right: 0; top: 100%; margin-top: 4px;
  background: #fff; border: 1px solid var(--line); border-radius: 8px;
  box-shadow: 0 6px 20px rgba(16,24,40,0.12); z-index: 10; overflow: hidden;
}
.suggest button { display: block; width: 100%; text-align: left; border: none; background: #fff; padding: 8px 12px; font: inherit; font-size: 14px; cursor: pointer; }
.suggest button:hover, .suggest button.active { background: var(--accent-soft); }
.editor-actions { display: flex; gap: 8px; margin-top: 4px; align-items: center; }
.editor-actions .save-edit { background: var(--accent); color: #fff; border: none; border-radius: 8px; padding: 9px 16px; font-weight: 600; cursor: pointer; font-size: 14px; }
.editor-actions .cancel-edit { background: transparent; color: var(--muted); border: none; cursor: pointer; font-size: 14px; }

.empty { text-align: center; color: var(--muted); padding: 48px 20px; border: 1px dashed var(--line); border-radius: 12px; background: var(--card); }
.empty .big { font-size: 15px; color: var(--text); margin: 0 0 4px; }
.loading { text-align: center; color: var(--muted); padding: 32px; }

